public static boolean isGeneralizationOf(String sourceClass, String targetClass) {
 // The class start with '+' (domain module) or with '-' (structural domain)
 if (sourceClass != null && sourceClass.length() > 0 
 && targetClass != null && targetClass.length() > 0) {
 String sourceClassSubstr = sourceClass.substring(1);
